create table if not exists public.plan_entitlements (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_id uuid not null references public.plans(id),feature_key text not null,source text not null default 'subscription' check(source in ('subscription','admin','promotion','system')),enabled boolean not null default true,quota bigint,valid_from timestamptz not null default now(),valid_until timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(user_id,feature_key)); create index if not exists plan_entitlements_user_idx on public.plan_entitlements(user_id,feature_key); create table if not exists public.usage_counters (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,metric_key text not null,period_start date not null,period_end date not null,quantity bigint not null default 0 check(quantity>=0),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,metric_key,period_start)); create index if not exists usage_counters_user_metric_idx on public.usage_counters(user_id,metric_key,period_start desc); create table if not exists public.billing_transactions (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,subscription_id uuid references public.subscriptions(id) on delete set null,type text not null check(type in ('subscription','one_time','ad_campaign','promotion','marketplace_fee')),status text not null default 'pending' check(status in ('pending','paid','failed','refunded','cancelled')),amount_minor bigint not null default 0 check(amount_minor>=0),currency char(3) not null default 'USD',provider text,provider_transaction_id text,description text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),paid_at timestamptz,refunded_at timestamptz,unique(provider,provider_transaction_id)); create index if not exists billing_transactions_user_idx on public.billing_transactions(user_id,created_at desc); create table if not exists public.advertisers (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,name text not null,company_name text,website_url text,is_active boolean not null default true,budget_minor bigint not null default 0 check(budget_minor>=0),currency char(3) not null default 'USD',created_at timestamptz not null default now()); create index if not exists advertisers_user_idx on public.advertisers(user_id); create table if not exists public.ad_campaigns (id uuid primary key default gen_random_uuid(),advertiser_id uuid not null references public.advertisers(id) on delete cascade,name text not null,status text not null default 'draft' check(status in ('draft','active','paused','completed','cancelled')),objective text not null default 'traffic' check(objective in ('traffic','engagement','conversion','awareness')),budget_minor bigint not null default 0 check(budget_minor>=0),spent_minor bigint not null default 0 check(spent_minor>=0),currency char(3) not null default 'USD',starts_at timestamptz,ends_at timestamptz,targeting jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create index if not exists ad_campaigns_status_idx on public.ad_campaigns(status,starts_at); create table if not exists public.ad_creatives (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.ad_campaigns(id) on delete cascade,title text not null,body text,media_url text,cta_label text,cta_url text,active boolean not null default true,created_at timestamptz not null default now()); create table if not exists public.ad_events (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.ad_campaigns(id) on delete cascade,creative_id uuid references public.ad_creatives(id) on delete set null,event_type text not null check(event_type in ('impression','click','conversion')),user_id uuid references auth.users(id) on delete set null,placement text,amount_minor bigint not null default 0 check(amount_minor>=0),currency char(3) not null default 'USD',occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb); create index if not exists ad_events_campaign_idx on public.ad_events(campaign_id,occurred_at desc); create index if not exists ad_events_type_idx on public.ad_events(event_type,occurred_at desc); create table if not exists public.promoted_listings (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,campaign_id uuid references public.ad_campaigns(id) on delete set null,status text not null default 'draft' check(status in ('draft','active','paused','completed','cancelled')),placement text not null default 'feed' check(placement in ('feed','search','category','home','featured')),starts_at timestamptz,ends_at timestamptz,budget_minor bigint not null default 0 check(budget_minor>=0),spent_minor bigint not null default 0 check(spent_minor>=0),currency char(3) not null default 'USD',created_at timestamptz not null default now()); create index if not exists promoted_listings_active_idx on public.promoted_listings(status,placement,starts_at); create table if not exists public.platform_revenue (id uuid primary key default gen_random_uuid(),source_type text not null check(source_type in ('subscription','advertising','promotion','marketplace_commission','affiliate','service')),source_id uuid,order_id uuid references public.orders(id) on delete set null,amount_minor bigint not null check(amount_minor>=0),currency char(3) not null default 'USD',status text not null default 'pending' check(status in ('pending','recognized','refunded','void')),description text,metadata jsonb not null default '{}'::jsonb,recognized_at timestamptz,created_at timestamptz not null default now()); create index if not exists platform_revenue_source_idx on public.platform_revenue(source_type,created_at desc); create index if not exists platform_revenue_order_idx on public.platform_revenue(order_id); create or replace function public.period_usage(p_user_id uuid,p_metric_key text,p_period_start date,p_period_end date) returns bigint language sql stable security invoker set search_path=public as $$ select coalesce((select quantity from public.usage_counters where user_id=p_user_id and metric_key=p_metric_key and period_start=p_period_start and period_end=p_period_end),0); $$; create or replace function public.increment_usage(p_metric_key text,p_quantity bigint default 1,p_user_id uuid default auth.uid()) returns bigint language plpgsql security invoker set search_path=public as $$ declare v_start date := date_trunc('month',current_date)::date; v_end date := (date_trunc('month',current_date)+interval '1 month-1 day')::date; v_value bigint; begin if p_user_id is null or p_user_id <> auth.uid() then raise exception 'unauthorized'; end if; if p_quantity <= 0 then raise exception 'quantity must be positive'; end if; insert into public.usage_counters(user_id,metric_key,period_start,period_end,quantity) values(p_user_id,p_metric_key,v_start,v_end,p_quantity) on conflict(user_id,metric_key,period_start) do update set quantity=public.usage_counters.quantity+excluded.quantity,updated_at=now() returning quantity into v_value; return v_value; end; $$; create or replace function public.get_user_entitlement(p_feature_key text,p_user_id uuid default auth.uid()) returns table(enabled boolean,quota bigint,plan_code text) language sql stable security invoker set search_path=public as $$ select pf.enabled,pf.quota,p.code from public.subscriptions s join public.plans p on p.id=s.plan_id join public.plan_features pf on pf.plan_id=p.id where s.user_id=p_user_id and s.status in ('trialing','active','past_due','paused') and pf.feature_key=p_feature_key and pf.enabled=true order by case when s.status='active' then 1 when s.status='trialing' then 2 else 3 end limit 1; $$; create or replace function public.record_platform_revenue(p_source_type text,p_amount_minor bigint,p_currency char(3),p_source_id uuid default null,p_order_id uuid default null,p_description text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin if p_amount_minor < 0 then raise exception 'amount must be non-negative'; end if; insert into public.platform_revenue(source_type,source_id,order_id,amount_minor,currency,status,description,recognized_at) values(p_source_type,p_source_id,p_order_id,p_amount_minor,p_currency,'recognized',p_description,now()) returning id into v_id; return v_id; end; $$; alter table public.plan_entitlements enable row level security; alter table public.usage_counters enable row level security; alter table public.billing_transactions enable row level security; alter table public.advertisers enable row level security; alter table public.ad_campaigns enable row level security; alter table public.ad_creatives enable row level security; alter table public.ad_events enable row level security; alter table public.promoted_listings enable row level security; alter table public.platform_revenue enable row level security; create policy plan_entitlements_owner_read on public.plan_entitlements for select using(user_id=auth.uid()); create policy usage_owner_read on public.usage_counters for select using(user_id=auth.uid()); create policy billing_owner_read on public.billing_transactions for select using(user_id=auth.uid()); create policy advertisers_owner_read on public.advertisers for select using(user_id=auth.uid()); create policy ad_campaigns_owner_read on public.ad_campaigns for select using(exists(select 1 from public.advertisers a where a.id=advertiser_id and a.user_id=auth.uid())); create policy ad_creatives_owner_read on public.ad_creatives for select using(exists(select 1 from public.ad_campaigns c join public.advertisers a on a.id=c.advertiser_id where c.id=campaign_id and a.user_id=auth.uid())); create policy ad_events_owner_read on public.ad_events for select using(exists(select 1 from public.ad_campaigns c join public.advertisers a on a.id=c.advertiser_id where c.id=campaign_id and a.user_id=auth.uid())); create policy promoted_listings_owner_read on public.promoted_listings for select using(owner_id=auth.uid()); grant execute on function public.current_user_plan(uuid) to anon,authenticated; grant execute on function public.user_has_plan_feature(text,uuid) to anon,authenticated; grant execute on function public.period_usage(uuid,text,date,date) to authenticated; grant execute on function public.increment_usage(text,bigint,uuid) to authenticated; grant execute on function public.get_user_entitlement(text,uuid) to authenticated; revoke all on public.platform_revenue from anon,authenticated; revoke all on public.ad_events from anon,authenticated;
